# Chemistry: inorganic chemistry. Classification of elements and periodicity;
# p-block elements; d- and f-block elements; coordination compounds (JEE
# (Main) 2027 syllabus units 9 to 12). Key written first; numerical value
# answers are computed here and asserted by N().

ITEMS = [
    # ---------- Practice Test 1: Section A ----------
    S(1, 2, "Ionisation enthalpy", "Which of Be, B, C and N has the lowest first ionisation enthalpy?",
      ["B", "Be", "C", "N"],
      "Ionisation enthalpy generally rises across a period, but B is lower than Be: its outer electron is in a 2p orbital, higher in energy and better shielded than Be's filled 2s pair."),
    S(1, 2, "Electron gain enthalpy", "Which of these elements has the least negative electron gain enthalpy?",
      ["Nitrogen", "Oxygen", "Fluorine", "Chlorine"],
      "Nitrogen's half-filled $2p^3$ subshell is stable, so adding an electron releases almost no energy (its value is close to zero). O, F and Cl all release energy, Cl the most."),
    S(1, 1, "Hydrogen halides", "Which hydrogen halide has the highest boiling point?",
      ["HF", "HCl", "HBr", "HI"],
      "HF molecules are linked by strong hydrogen bonds, so HF boils at about 20 °C, far above HCl. Among the other three the boiling point rises with size: HCl < HBr < HI."),
    S(1, 2, "Oxoacids of phosphorus", "Which oxoacid of phosphorus is dibasic?",
      ["H₃PO₃", "H₃PO₄", "H₃PO₂", "H₄P₂O₇"],
      "Only H atoms bonded to O are acidic. H$_3$PO$_3$ has two P-OH groups and one P-H bond, so it is dibasic. H$_3$PO$_4$ is tribasic and H$_3$PO$_2$ is monobasic."),
    S(1, 2, "f-block elements", "Why are cerium(IV) compounds good oxidising agents?",
      ["Ce⁴⁺ readily changes to the more stable Ce³⁺", "Ce⁴⁺ has a half-filled 4f subshell", "Ce⁴⁺ is a very large ion", "Ce⁴⁺ has unpaired 5d electrons"],
      "+3 is the characteristic lanthanoid state. Ce$^{4+}$ (an empty 4f shell) is stable enough to exist but readily gains an electron to become Ce$^{3+}$, oxidising something else. Ce$^{4+}$ has no 4f electrons, so it is not half-filled."),
    S(1, 2, "Magnetic moment", "What is the spin-only magnetic moment of the high-spin Co$^{2+}$ ion ($Z$ of Co = 27)?",
      ["3.87 BM", "1.73 BM", "2.83 BM", "4.90 BM"],
      "Co$^{2+}$ is $3d^7$; high-spin it has 3 unpaired electrons, and $\\mu = \\sqrt{3 \\times 5} = \\sqrt{15} \\approx 3.87$ BM. 4.90 BM is for 4 unpaired electrons, as in Fe$^{2+}$."),
    S(1, 2, "Valence bond theory", "What are the hybridisation and shape of $[\\text{Ni(CN)}_4]^{2-}$?",
      ["dsp², square planar", "sp³, tetrahedral", "sp³d², octahedral", "d²sp³, octahedral"],
      "Ni$^{2+}$ is $3d^8$. The strong-field CN$^-$ pairs up the d electrons, freeing one 3d orbital for dsp$^2$ hybridisation, so the complex is square planar and diamagnetic. [NiCl$_4$]$^{2-}$, with a weak field, is the tetrahedral one."),
    # ---------- Practice Test 1: Section B ----------
    N(1, 2, "Crystal field theory", "How many unpaired electrons does the high-spin complex $[\\text{Fe(H}_2\\text{O)}_6]^{2+}$ have?",
      4, 4,
      "Fe$^{2+}$ is $3d^6$. Water is a weak-field ligand, so the configuration is $t_{2g}^4 e_g^2$: one pair and four single electrons."),
    # ---------- Practice Test 2: Section A ----------
    S(2, 1, "Ionic radius", "Which of these isoelectronic ions is the smallest?",
      ["Ca²⁺", "S²⁻", "Cl⁻", "K⁺"],
      "All have 18 electrons. Ca$^{2+}$ has the most protons (20) pulling on them, so it is the smallest; S$^{2-}$, with 16 protons, is the largest."),
    S(2, 2, "Group 15 hydrides", "Which group 15 hydride is the strongest reducing agent?",
      ["BiH₃", "NH₃", "PH₃", "AsH₃"],
      "Down the group the E-H bond weakens, so the hydride gives up hydrogen more easily and reducing power rises from NH$_3$ to BiH$_3$."),
    S(2, 2, "Interhalogen compounds", "What is the shape of the ClF$_3$ molecule?",
      ["T-shaped", "Trigonal planar", "Pyramidal", "See-saw"],
      "Cl has 3 bond pairs and 2 lone pairs, a trigonal bipyramidal arrangement. The lone pairs take two equatorial positions, leaving a T shape. Trigonal planar would need no lone pairs."),
    S(2, 2, "Potassium dichromate", "In acidic solution, how many electrons does each dichromate ion, Cr$_2$O$_7^{2-}$, gain when it acts as an oxidising agent?",
      ["6", "1", "2", "3"],
      "Each Cr goes from +6 to +3, gaining 3 electrons, and the ion has two Cr atoms, so it gains 6. 3 is the figure per chromium atom."),
    S(2, 2, "Lanthanoids", "Which lanthanoid commonly shows a +2 oxidation state as well as +3?",
      ["Europium", "Cerium", "Lutetium", "Gadolinium"],
      "Eu$^{2+}$ is $4f^7$, a stable half-filled subshell, so europium readily forms +2 compounds. Cerium's extra state is +4, and Gd$^{3+}$ and Lu$^{3+}$ are already $4f^7$ and $4f^{14}$."),
    S(2, 2, "Crystal field theory", "Which of these complexes is low-spin?",
      ["[Co(NH₃)₆]³⁺", "[CoF₆]³⁻", "[Mn(H₂O)₆]²⁺", "[MnCl₄]²⁻"],
      "Co$^{3+}$ is $3d^6$, and ammonia's field is large enough with a 3+ ion to pair all six electrons in $t_{2g}$, a low-spin, diamagnetic complex. F$^-$, H$_2$O and Cl$^-$ are weak-field ligands here."),
    S(2, 2, "Isomerism in complexes", "$[\\text{Co(NH}_3)_5\\text{Br}]\\text{SO}_4$ and $[\\text{Co(NH}_3)_5\\text{SO}_4]\\text{Br}$ are which kind of isomers?",
      ["Ionisation isomers", "Linkage isomers", "Coordination isomers", "Hydrate isomers"],
      "The two swap an ion between the coordination sphere and the counter-ion, so they give different ions in solution: one gives SO$_4^{2-}$, the other Br$^-$. Linkage isomers differ in which atom of a ligand binds."),
    # ---------- Practice Test 2: Section B ----------
    N(2, 2, "Oxides of phosphorus", "How many P-O-P bridges are there in one molecule of P$_4$O$_{10}$?",
      6, 6,
      "The four P atoms sit at the corners of a tetrahedron and each of its 6 edges is bridged by an O atom. The other 4 O atoms are terminal P=O groups."),
    # ---------- Drill only ----------
    S(0, 1, "Diagonal relationship", "Which pair of elements shows a diagonal relationship?",
      ["Li and Mg", "Li and Na", "Be and Mg", "Li and Be"],
      "Li (group 1, period 2) resembles Mg (group 2, period 3), one step down and to the right, because their charge-to-size ratios are similar. Li and Na are in the same group."),
    S(0, 2, "Inert pair effect", "Why is lead(IV) oxide, PbO$_2$, a strong oxidising agent?",
      ["Pb²⁺ is more stable than Pb⁴⁺", "Pb⁴⁺ is more stable than Pb²⁺", "Lead is a non-metal", "PbO₂ is strongly basic"],
      "Down group 14 the $6s^2$ pair is reluctant to bond (the inert pair effect), so +2 is lead's stable state. PbO$_2$ readily gains electrons to reach it, oxidising other substances."),
    S(0, 1, "Colour of ions", "Statement I: Copper(II) salts are coloured but zinc(II) salts are white. Statement II: The Zn$^{2+}$ ion has a completely filled $3d^{10}$ subshell. Which is correct?",
      [STATEMENTS[0], STATEMENTS[1], STATEMENTS[2], STATEMENTS[3]],
      "Colour in these ions comes from d-d transitions. Cu$^{2+}$ ($3d^9$) has a vacancy to excite into; Zn$^{2+}$ ($3d^{10}$) has none, so its salts are white. Both statements are true."),
    S(0, 1, "Ligands", "Which of these ligands is ambidentate?",
      ["NO₂⁻", "NH₃", "H₂O", "Ethane-1,2-diamine"],
      "An ambidentate ligand can bind through either of two atoms: NO$_2^-$ binds through N (nitro) or O (nitrito), giving linkage isomers. Ethane-1,2-diamine uses both its N atoms at once, which makes it bidentate."),
    N(0, 1, "Electronic configuration", "How many unpaired electrons does a chromium atom ($Z = 24$) have in its ground state?",
      5 + 1, 6,
      "Chromium is $[\\text{Ar}]\\,3d^5 4s^1$: a half-filled d subshell is extra stable, so one 4s electron moves to 3d. That leaves 5 + 1 = 6 unpaired electrons."),
    N(0, 1, "Werner's theory", "How many ions does one formula unit of $[\\text{Co(NH}_3)_6]\\text{Cl}_3$ give in water?",
      1 + 3, 4,
      "The complex ion $[\\text{Co(NH}_3)_6]^{3+}$ stays intact and the three Cl$^-$ outside the brackets are free: 1 + 3 = 4 ions."),
]
